},{"v":"1","label":"Tandem"},{"v":"2","label":"Delad vagn"}]},{"id":"stroke_mm","step":6,"title_sv":"Slaglängd","title_en":"Order stroke","required":true,"type":"numeric","min":1,"max":6000,"unit":"mm"},{"id":"home_sensor","step":7,"title_sv":"Hemgivare","title_en":"Home sensor","required":true,"type":"single_select","options":[{"v":"0","label":"Utan"},{"v":"1","label":"Reed, 2-ledare, NO, intern"},{"v":"A","label":"PNP, 3-ledare, NO, intern"},{"v":"K","label":"NPN, 3-ledare, NO, intern"},{"v":"3","label":"Reed, NO, M8-kontakt, 0,3 m kabel"},{"v":"C","label":"PNP, NO, M8-kontakt, 0,3 m kabel"},{"v":"M","label":"NPN, NO, M8-kontakt, 0,3 m kabel"},{"v":"5","label":"Reed, NO, fria ledare, 3 m kabel"},{"v":"E","label":"PNP, NO, fria ledare, 3 m kabel"},{"v":"P","label":"NPN, NO, fria ledare, 3 m kabel"},{"v":"7","label":"Reed, NO, fria ledare, 10 m kabel"},{"v":"G","label":"PNP, NO, fria ledare, 10 m kabel"},{"v":"R","label":"NPN, NO, fria ledare, 10 m kabel"}]},{"id":"limit_sensor","step":8,"title_sv":"Gränslägesgivare","title_en":"Limit sensor","required":true,"type":"single_select","options":[{"v":"0","label":"Utan"},{"v":"2","label":"Reed, 2-ledare, NC, intern"},{"v":"B","label":"PNP, 3-ledare, NC, intern"},{"v":"L","label":"NPN, 3-ledare, NC, intern"},{"v":"4","label":"Reed, NC, M8-kontakt, 0,3 m kabel"},{"v":"D","label":"PNP, NC, M8-kontakt, 0,3 m kabel"},{"v":"N","label":"NPN, NC, M8-kontakt, 0,3 m kabel"},{"v":"6","label":"Reed, NC, fria ledare, 3 m kabel"},{"v":"F","label":"PNP, NC, fria ledare, 3 m kabel"},{"v":"Q","label":"NPN, NC, fria ledare, 3 m kabel"},{"v":"8","label":"Reed, NC, fria ledare, 10 m kabel"},{"v":"H","label":"PNP, NC, fria ledare, 10 m kabel"},{"v":"S","label":"NPN, NC, fria ledare, 10 m kabel"}]},{"id":"sensor_position","step":9,"title_sv":"Gränslägesgivarens läge","title_en":"Limit sensor position","required":true,"type":"single_select","options":[{"v":"0","label":"Utan givare"},{"v":"1","label":"10 mm"},{"v":"2","label":"20 mm"},{"v":"3","label":"30 mm"},{"v":"4","label":"40 mm"},{"v":"5","label":"50 mm"},{"v":"6","label":"60 mm"},{"v":"7","label":"70 mm"},{"v":"8","label":"80 mm"},{"v":"9","label":"90 mm"},{"v":"A","label":"100 mm"},{"v":"B","label":"110 mm"},{"v":"C","label":"120 mm"},{"v":"D","label":"130 mm"},{"v":"E","label":"140 mm"},{"v":"F","label":"150 mm"},{"v":"G","label":"160 mm"},{"v":"H","label":"170 mm"},{"v":"J","label":"180 mm"},{"v":"K","label":"190 mm"},{"v":"L","label":"200 mm"}]},{"id":"mounting_kit","step":10,"title_sv":"Monteringssats","title_en":"Mounting kit","required":true,"type":"single_select","options":[{"v":"00","label":"Utan monteringssats"},{"v":"A7","label":"Växel PS60 (storlek 15, 18)"},{"v":"A8","label":"Växel PS90 (storlek 18)"},{"v":"A9","label":"Växel PS115 (storlek 24)"},{"v":"C0","label":"Växel LP050 (storlek 08, 11)"},{"v":"C1","label":"Växel PV60-TA eller LP070 (storlek 11, 15, 18)"},{"v":"C2","label":"Växel PV90-TA eller LP090 (storlek 18)"},{"v":"C3","label":"Växel PV115-TA eller LP120 (storlek 24)"}]},{"id":"guide_mounting","step":11,"title_sv":"Växelmontage","title_en":"Gear mounting","required":true,"type":"single_select","options":[{"v":"00","label":"Utan"},{"v":"A2","label":"LP050, utväxling 5 (storlek 08, 11)"},{"v":"A3","label":"LP050, utväxling 10 (storlek 08, 11)"},{"v":"B1","label":"LP070, utväxling 3 (storlek 11, 15)"},{"v":"B2","label":"LP070, utväxling 5 (storlek 11, 15)"},{"v":"B3","label":"LP070, utväxling 10 (storlek 11, 15)"},{"v":"C1","label":"LP090, utväxling 3 (storlek 18)"},{"v":"C2","label":"LP090, utväxling 5 (storlek 18)"},{"v":"C3","label":"LP090, utväxling 10 (storlek 18)"},{"v":"D1","label":"LP120, utväxling 3 (storlek 24)"},{"v":"D2","label":"LP120, utväxling 5 (storlek 24)"},{"v":"D3","label":"LP120, utväxling 10 (storlek 24)"}]}]}'::jsonb,
        'Parker HMR linjärdrivning', 'Parker HMR linear drive', 'linear-module')
on conflict (schema_id) do update set
  schema_json = excluded.schema_json,
  title_sv = excluded.title_sv,
  title_en = excluded.title_en;

update configurator_families set
  stroke_min_mm = 1,
  stroke_max_mm = 6000,
  order_code_template = 'HMR{drive}{size}{design}{pitch_or_mount}{carriage}-{stroke_mm#4}-{home_sensor}{limit_sensor}{sensor_position}00{mounting_kit}{guide_mounting}',
  rules_schema_id = 'SCHEMA-HMR-V1'
where slug = 'hmr';


delete from configurator_param_values v using configurator_params p, configurator_families f
  where v.param_id = p.id and p.family_id = f.id and f.slug = 'hmr';
delete from configurator_params p using configurator_families f
  where p.family_id = f.id and f.slug = 'hmr';

