     jsonb_to_recordset('[{"param_key":"drive","label":"Drivning","param_type":"select","sort_order":1,"required":true,"min_value":null,"max_value":null},{"param_key":"size","label":"Storlek","param_type":"select","sort_order":2,"required":true,"min_value":null,"max_value":null},{"param_key":"design","label":"Profil","param_type":"select","sort_order":3,"required":true,"min_value":null,"max_value":null},{"param_key":"pitch_or_mount","label":"Stigning / motorläge","param_type":"select","sort_order":4,"required":true,"min_value":null,"max_value":null},{"param_key":"carriage","label":"Vagn","param_type":"select","sort_order":5,"required":true,"min_value":null,"max_value":null},{"param_key":"stroke_mm","label":"Slaglängd","param_type":"number","sort_order":6,"required":true,"min_value":1,"max_value":6000},{"param_key":"home_sensor","label":"Hemgivare","param_type":"select","sort_order":7,"required":true,"min_value":null,"max_value":null},{"param_key":"limit_sensor","label":"Gränslägesgivare","param_type":"select","sort_order":8,"required":true,"min_value":null,"max_value":null},{"param_key":"sensor_position","label":"Gränslägesgivarens läge","param_type":"select","sort_order":9,"required":true,"min_value":null,"max_value":null},{"param_key":"mounting_kit","label":"Monteringssats","param_type":"select","sort_order":10,"required":true,"min_value":null,"max_value":null},{"param_key":"guide_mounting","label":"Växelmontage","param_type":"select","sort_order":11,"required":true,"min_value":null,"max_value":null}]'::jsonb)
