"severity":"error","if_json":{"and":[{"==":[{"var":"drive"},"S"]},{"==":[{"var":"size"},"18"]},{"in":[{"var":"pitch_or_mount"},["05","10","12","16","20","25","32"]]},{"not":{"in":[{"var":"pitch_or_mount"},["10","25"]]}}]},"message_sv":"Storlek 18 (profilbredd 180 mm) finns med skruvstigning 10 och 25 mm.","message_en":"Size 18 (profile width 180 mm) is available with spindle pitch 10 and 25 mm.","goto_step":"hmr-stigning"},{"severity":"error","if_json":{"and":[{"==":[{"var":"size"},"18"]},{"!=":[{"var":"mounting_kit"},""]},{"not":{"in":[{"var":"mounting_kit"},["00","A7","A8","C1","C2"]]}}]},"message_sv":"Storlek 18 tar monteringssats 00, A7, A8, C1 och C2.","message_en":"Size 18 takes mounting kit 00, A7, A8, C1 or C2.","goto_step":"hmr-monteringssats"},{"severity":"error","if_json":{"and":[{"==":[{"var":"size"},"18"]},{"!=":[{"var":"guide_mounting"},""]},{"not":{"in":[{"var":"guide_mounting"},["00","C1","C2","C3"]]}}]},"message_sv":"Storlek 18 tar växelmontage 00, C1, C2 och C3.","message_en":"Size 18 takes gear mounting 00, C1, C2 or C3.","goto_step":"hmr-vaxel"},{"severity":"error","if_json":{"and":[{"==":[{"var":"drive"},"S"]},{"==":[{"var":"size"},"24"]},{"in":[{"var":"pitch_or_mount"},["05","10","12","16","20","25","32"]]},{"not":{"in":[{"var":"pitch_or_mount"},["10","32"]]}}]},"message_sv":"Storlek 24 (profilbredd 240 mm) finns med skruvstigning 10 och 32 mm.","message_en":"Size 24 (profile width 240 mm) is available with spindle pitch 10 and 32 mm.","goto_step":"hmr-stigning"},{"severity":"error","if_json":{"and":[{"==":[{"var":"size"},"24"]},{"!=":[{"var":"mounting_kit"},""]},{"not":{"in":[{"var":"mounting_kit"},["00","A9","C3"]]}}]},"message_sv":"Storlek 24 tar monteringssats 00, A9 och C3.","message_en":"Size 24 takes mounting kit 00, A9 or C3.","goto_step":"hmr-monteringssats"},{"severity":"error","if_json":{"and":[{"==":[{"var":"size"},"24"]},{"!=":[{"var":"guide_mounting"},""]},{"not":{"in":[{"var":"guide_mounting"},["00","D1","D2","D3"]]}}]},"message_sv":"Storlek 24 tar växelmontage 00, D1, D2 och D3.","message_en":"Size 24 takes gear mounting 00, D1, D2 or D3.","goto_step":"hmr-vaxel"},{"severity":"error","if_json":{"and":[{"==":[{"var":"drive"},"S"]},{"in":[{"var":"carriage"},["2"]]}]},"message_sv":"Delad vagn finns bara på remdriften. En skruv kan inte driva två vagnar åt olika håll.","message_en":"The bi-part carriage is only available on the belt drive. A screw cannot drive two carriages in opposite directions.","goto_step":"hmr-vagn"},{"severity":"error","if_json":{"and":[{"==":[{"var":"drive"},"S"]},{"==":[{"var":"size"},"08"]},{">":[{"var":"stroke_mm"},1200]}]},"message_sv":"Kulskruv i storlek 08 går till 1200 mm slaglängd.","message_en":"The ball screw in size 08 goes up to 1200 mm stroke.","goto_step":"hmr-slag"},{"severity":"error","if_json":{"and":[{"==":[{"var":"drive"},"S"]},{"==":[{"var":"size"},"11"]},{">":[{"var":"stroke_mm"},1500]}]},"message_sv":"Kulskruv i storlek 11 går till 1500 mm slaglängd.","message_en":"The ball screw in size 11 goes up to 1500 mm stroke.","goto_step":"hmr-slag"},{"severity":"error","if_json":{"and":[{"==":[{"var":"drive"},"S"]},{"==":[{"var":"size"},"15"]},{">":[{"var":"stroke_mm"},2500]}]},"message_sv":"Kulskruv i storlek 15 går till 2500 mm slaglängd.","message_en":"The ball screw in size 15 goes up to 2500 mm stroke.","goto_step":"hmr-slag"},{"severity":"error","if_json":{"and":[{"==":[{"var":"drive"},"S"]},{"==":[{"var":"size"},"18"]},{">":[{"var":"stroke_mm"},3400]}]},"message_sv":"Kulskruv i storlek 18 går till 3400 mm slaglängd.","message_en":"The ball screw in size 18 goes up to 3400 mm stroke.","goto_step":"hmr-slag"},{"severity":"error","if_json":{"and":[{"==":[{"var":"drive"},"S"]},{"==":[{"var":"size"},"24"]},{">":[{"var":"stroke_mm"},4000]}]},"message_sv":"Kulskruv i storlek 24 går till 4000 mm slaglängd.","message_en":"The ball screw in size 24 goes up to 4000 mm stroke.","goto_step":"hmr-slag"},{"severity":"error","if_json":{"and":[{"==":[{"var":"drive"},"B"]},{"==":[{"var":"size"},"08"]},{">":[{"var":"stroke_mm"},3000]}]},"message_sv":"Remdrift i storlek 08 går till 3000 mm slaglängd.","message_en":"The belt drive in size 08 goes up to 3000 mm stroke.","goto_step":"hmr-slag"},{"severity":"error","if_json":{"and":[{"==":[{"var":"drive"},"B"]},{"==":[{"var":"size"},"11"]},{">":[{"var":"stroke_mm"},4000]}]},"message_sv":"Remdrift i storlek 11 går till 4000 mm slaglängd.","message_en":"The belt drive in size 11 goes up to 4000 mm stroke.","goto_step":"hmr-slag"},{"severity":"error","if_json":{"and":[{"==":[{"var":"drive"},"B"]},{"==":[{"var":"size"},"15"]},{">":[{"var":"stroke_mm"},6000]}]},"message_sv":"Remdrift i storlek 15 går till 6000 mm slaglängd.","message_en":"The belt drive in size 15 goes up to 6000 mm stroke.","goto_step":"hmr-slag"},{"severity":"info","if_json":{"and":[{"==":[{"var":"drive"},"S"]},{"==":[{"var":"size"},"08"]},{"==":[{"var":"pitch_or_mount"},"12"]}]},"message_sv":"Med 12 mm stigning går storlek 08 0.6 m/s. Med 5 mm blir det 0.25 m/s — samma tryckkraft, 820 N, men motorn behöver mer moment vid den grova stigningen.","message_en":"With 12 mm pitch size 08 runs at 0.6 m/s. With 5 mm it is 0.25 m/s — the same thrust, 820 N, but the motor needs more torque at the coarse pitch.","goto_step":"hmr-stigning"},{"severity":"info","if_json":{"and":[{"==":[{"var":"drive"},"S"]},{"==":[{"var":"size"},"11"]},{"==":[{"var":"pitch_or_mount"},"16"]}]},"message_sv":"Med 16 mm stigning går storlek 11 0.8 m/s. Med 5 mm blir det 0.25 m/s — samma tryckkraft, 2200 N, men motorn behöver mer moment vid den grova stigningen.","message_en":"With 16 mm pitch size 11 runs at 0.8 m/s. With 5 mm it is 0.25 m/s — the same thrust, 2200 N, but the motor needs more torque at the coarse pitch.","goto_step":"hmr-stigning"},{"severity":"info","if_json":{"and":[{"==":[{"var":"drive"},"S"]},{"==":[{"var":"size"},"15"]},{"==":[{"var":"pitch_or_mount"},"20"]}]},"message_sv":"Med 20 mm stigning går storlek 15 1 m/s. Med 5 mm blir det 0.25 m/s — samma tryckkraft, 2600 N, men motorn behöver mer moment vid den grova stigningen.","message_en":"With 20 mm pitch size 15 runs at 1 m/s. With 5 mm it is 0.25 m/s — the same thrust, 2600 N, but the motor needs more torque at the coarse pitch.","goto_step":"hmr-stigning"},{"severity":"info","if_json":{"and":[{"==":[{"var":"drive"},"S"]},{"==":[{"var":"size"},"18"]},{"==":[{"var":"pitch_or_mount"},"25"]}]},"message_sv":"Med 25 mm stigning går storlek 18 1.25 m/s. Med 10 mm blir det 0.5 m/s — samma tryckkraft, 4800 N, men motorn behöver mer moment vid den grova stigningen.","message_en":"With 25 mm pitch size 18 runs at 1.25 m/s. With 10 mm it is 0.5 m/s — the same thrust, 4800 N, but the motor needs more torque at the coarse pitch.","goto_step":"hmr-stigning"},{"severity":"info","if_json":{"and":[{"==":[{"var":"drive"},"S"]},{"==":[{"var":"size"},"24"]},{"==":[{"var":"pitch_or_mount"},"32"]}]},"message_sv":"Med 32 mm stigning går storlek 24 1.6 m/s. Med 10 mm blir det 0.5 m/s — samma tryckkraft, 5000 N, men motorn behöver mer moment vid den grova stigningen.","message_en":"With 32 mm pitch size 24 runs at 1.6 m/s. With 10 mm it is 0.5 m/s — the same thrust, 5000 N, but the motor needs more torque at the coarse pitch.","goto_step":"hmr-stigning"},{"severity":"warn","if_json":{"and":[{"==":[{"var":"drive"},"B"]},{"==":[{"var":"size"},"15"]},{"in":[{"var":"pitch_or_mount"},["AP","CP","AD","CD"]]}]},"message_sv":"I lägena AP, CP, AD och CD ger storlek 15 630 N och 125 mm per varv. I BD och DD blir det 1050 N och 100 mm per varv — remmen läggs om.","message_en":"In orientations AP, CP, AD and CD size 15 gives 630 N and 125 mm per rev. In BD and DD it is 1050 N and 100 mm per rev — the belt is routed differently.","goto_step":"hmr-stigning"},{"severity":"warn","if_json":{"and":[{"==":[{"var":"drive"},"B"]},{"in":[{"var":"size"},["18","24"]]}]},"message_sv":"Katalogen ger beställkoden för remdrift i storlek 18 och 24 men inte hastighets- och kraftdata. Kontrollera