insert into product_specs (product_id, key, value)
select p.id, v.key, v.value
from products p
cross join lateral (values
  ('drive', 'Ball screw'),
  ('sizes', '08 (85 mm), 11 (110 mm), 15 (150 mm), 18 (180 mm), 24 (240 mm)'),
  ('stroke_max_mm', '1200–4000 beroende på storlek'),
  ('max_speed_ms', '0.25–1.6 beroende på stigning'),
  ('max_acceleration_ms2', '10'),
  ('repeatability_um', '±20'),
  ('max_thrust_n', '820–5000 beroende på storlek'),
  ('order_code_length', '25'),
  ('order_code_example', 'HMRS15B050-0500-000000000')
) as v(key, value)
where p.sku = 'PARKER-HMRS'
  and not exists (select 1 from product_specs x where x.product_id = p.id and x.key = v.key);

insert into product_specs (product_id, key, value)
select p.id, v.key, v.value
from products p
cross join lateral (values
  ('drive', 'Toothed belt'),
  ('sizes', '08 (85 mm), 11 (110 mm), 15 (150 mm), 18 (180 mm), 24 (240 mm)'),
  ('stroke_max_mm', '3000–6000 för storlek 08–15; 18 och 24 ej angivna i katalogen'),
  ('max_speed_ms', '2–5 för storlek 08–15'),
  ('max_acceleration_ms2', '30–50'),
  ('repeatability_um', '±50'),
  ('max_thrust_n', '295–1050 för storlek 08–15'),
  ('order_code_length', '25'),
  ('order_code_example', 'HMRB15BBD0-0500-000000000')
) as v(key, value)
where p.sku = 'PARKER-HMRB'
  and not exists (select 1 from product_specs x where x.product_id = p.id and x.key = v.key);

commit;

